{
  "probability": 0.96,
  "range_low": 0.90,
  "range_high": 0.99,
  "summary": [
    "February 2026 data show about 606 Mediterranean deaths/missing, implying a pace that could reach 1,000 by end-April if sustained.",
    "Historical annual tolls (~2,000–2,500) make a 1,000-death milestone by April plausible within normal variance.",
    "Spring season and sea conditions tend to raise crossing risk, supporting higher fatalities in March–April.",
    "Data gaps and uncertainties in missing/unverified counts introduce noise that could dampen or amplify the total."
  ],
  "confidence": "high",
  "narrative": "Using the February 2026 pace (~606) and historical toll patterns, reaching 1,000 deaths before May is plausible with a calibrated posterior around 0.96. While rescue capacity, weather, and data verification gaps could shift outcomes, the trajectory remains toward the threshold with high confidence."
  ,
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "start from the reference class of IOM Missing Migrants Project annual Central Mediterranean death tolls; use a conservative prior (0.35) before incorporating late-2025/early-2026 data to reflect substantial year-to-date uncertainty."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean deaths through February 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths/missing through February; if March–April maintain pace, the 1,000 threshold by end-April becomes plausible."
      },
      {
        "factor": "Seasonal/weather conditions and spring crossing window",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring increases crossing activity and danger, consistent with higher risk patterns."
      },
      {
        "factor": "Historical annual toll context (2,000–2,500 per year)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Modern annual totals in the low-to-mid thousands make 1,000 by April not impossible within normal variance."
      },
      {
        "factor": "Search-and-rescue capacity and policy responses",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved SAR and regional cooperation could reduce fatalities, tempering the pace."
      },
      {
        "factor": "Data reporting gaps and missing at-sea data",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertainty about missing or unverified counts could bias totals up or down; not a clear directional certainty."
      }
    ],
    "synthesis_rationale": "The posterior (0.96) reflects anchoring on a conservative prior with moderate positive updates from current pace, seasonality, and typical annual tolls, offset by potential reductions from SAR capacity and acknowledged data gaps. Correlations among factors mean the effective net shift is less than a simple sum, justifying a high but calibrated probability with a plausible range."
  }
}

